<?php
require_once '_bootstrap.php';
$r=$conn->query("SELECT id,codigo FROM pedidos WHERE empresa_id=1 AND status='AGUARDANDO_PAGAMENTO' AND estoque_reservado=1 AND reserva_expira_em IS NOT NULL AND reserva_expira_em<NOW() LIMIT 100");
while($pedido=$r->fetch_assoc()){$id=(int)$pedido['id'];$conn->begin_transaction();try{$lock=$conn->prepare("SELECT id,status,estoque_reservado FROM pedidos WHERE id=? FOR UPDATE");$lock->bind_param('i',$id);$lock->execute();$p=$lock->get_result()->fetch_assoc();if(!$p||$p['status']!=='AGUARDANDO_PAGAMENTO'||!(int)$p['estoque_reservado']){$conn->rollback();continue;}$it=$conn->prepare('SELECT pi.produto_id,pi.quantidade,pr.estoque_atual FROM pedido_itens pi JOIN produtos pr ON pr.id=pi.produto_id WHERE pi.pedido_id=? FOR UPDATE');$it->bind_param('i',$id);$it->execute();$rows=$it->get_result();while($x=$rows->fetch_assoc()){$antes=(int)$x['estoque_atual'];$qtd=(int)$x['quantidade'];$depois=$antes+$qtd;$up=$conn->prepare('UPDATE produtos SET estoque_atual=? WHERE id=?');$pid=(int)$x['produto_id'];$up->bind_param('ii',$depois,$pid);$up->execute();$m=$conn->prepare("INSERT INTO estoque_movimentacoes(empresa_id,produto_id,tipo,quantidade,estoque_anterior,estoque_posterior,referencia,observacao) VALUES(1,?,'DEVOLUCAO',?,?,?,?,'Reserva expirada')");$ref=$pedido['codigo'];$m->bind_param('iiiis',$pid,$qtd,$antes,$depois,$ref);$m->execute();$movId=(int)$conn->insert_id;enfileirarSheets($conn,1,'MOVIMENTACAO_ESTOQUE','ESTOQUE_MOVIMENTACAO',$movId);}$up=$conn->prepare("UPDATE pedidos SET status='CANCELADO',estoque_reservado=0 WHERE id=?");$up->bind_param('i',$id);$up->execute();$pg=$conn->prepare("UPDATE pagamentos SET status='CANCELADO' WHERE pedido_id=? AND status='PENDENTE'");$pg->bind_param('i',$id);$pg->execute();criarEventoENotificar($conn,1,0,'Reserva expirada '.$pedido['codigo'],'Pedido cancelado e estoque devolvido.','INFORMATIVO','PEDIDO',$id,'RESERVA_EXPIRADA:'.$id,'VENDAS','RESERVA_EXPIRADA');enfileirarSheets($conn,1,'PEDIDO','PEDIDO',$id);$pgs=$conn->prepare("SELECT id FROM pagamentos WHERE pedido_id=? ORDER BY id DESC LIMIT 1");$pgs->bind_param('i',$id);$pgs->execute();if($pr=$pgs->get_result()->fetch_assoc())enfileirarSheets($conn,1,'PAGAMENTO','PAGAMENTO',(int)$pr['id']);$conn->commit();echo "Expirado {$pedido['codigo']}\n";}catch(Throwable $e){$conn->rollback();fwrite(STDERR,$e->getMessage()."\n");}}
